/** One network's badge, or nothing when we hold no artwork for it. Untitled marks are decorative. */
export function NetworkArtwork({
  brand,
  size,
  title,
  className,
}: {
  brand: string
  size: number
  title?: string
  className?: string
}) {
  const artwork = NETWORK_ARTWORK[brand]
  if (!artwork) return null

  return (
    // biome-ignore lint/a11y/noSvgWithoutTitle: a titled mark carries its `title`; an untitled one is decorative (aria-hidden).
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="currentColor"
      aria-hidden={title ? undefined : true}
      className={className}
    >
      {title ? <title>{title}</title> : null}
      {artwork}
    </svg>
  )
}

/**
 * One network, as artwork where we hold it and as a neutral bordered chip where we do not.
 *
 * The fallback is the `+N` chip's treatment rather than a coloured invention, because the badges'
 * provenance is unrecorded and their licence not yet cleared. Adding more colour badges of unknown
 * origin would widen a gate that is already open.
 */
export function NetworkMark({ brand, className }: { brand: string; className?: string }) {
  const { t } = useLingui()
  const label = networkName(brand)

  if (NETWORK_ARTWORK[brand]) {
    return <NetworkArtwork brand={brand} size={40} title={label} className={cn(networkMark(), 'shrink-0', className)} />
  }

  return <NetworkChip className={className}>{brand === 'unknown' ? t`Card` : label.slice(0, 6)}</NetworkChip>
}
